package com.curso.cotacao;
import com.curso.domains.enums.FonteCotacao;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class CotacaoOrchestratorTest{
 @Test void respeitaOrdemEInterrompeNoSucesso(){CotacaoProvider b=mock(CotacaoProvider.class),a=mock(CotacaoProvider.class),h=mock(CotacaoProvider.class);when(b.fonte()).thenReturn(FonteCotacao.BRAPI);when(a.fonte()).thenReturn(FonteCotacao.ALPHA_VANTAGE);when(b.buscar("PETR4")).thenThrow(new ProviderCotacaoException(FonteCotacao.BRAPI,"falhou"));when(a.buscar("PETR4")).thenReturn(new CotacaoAtual("PETR4","Petrobras","B3",new BigDecimal("30"),FonteCotacao.ALPHA_VANTAGE));var r=new CotacaoOrchestrator(List.of(b,a,h)).buscar("petr4");assertEquals(FonteCotacao.ALPHA_VANTAGE,r.fonte());verifyNoInteractions(h);}
 @Test void agregaFalhaTotal(){List<CotacaoProvider> ps=new ArrayList<>();for(FonteCotacao f:FonteCotacao.values()){CotacaoProvider p=mock(CotacaoProvider.class);when(p.fonte()).thenReturn(f);when(p.buscar("PETR4")).thenThrow(new ProviderCotacaoException(f,"falhou"));ps.add(p);}var ex=assertThrows(CotacaoIndisponivelException.class,()->new CotacaoOrchestrator(ps).buscar("PETR4"));assertEquals(3,ex.getTentativas().size());assertFalse(ex.getMessage().contains("token"));}}
